from django.db import migrations, models

FAQ_DATA = [('Getting started', 'What is ReRevi?', '<p>ReRevi is an independent practice website for Eduqas GCSE Religious Studies Route A. Build practice sets, work online or on paper, and compare your answers with available marking guidance. It is not an official Eduqas website.</p>'), ('Getting started', 'Which components does ReRevi cover?', '<p>Component 1 covers Relationships, Life and Death, Good and Evil, and Human Rights. Component 2 covers Christianity and Component 3 covers Islam, including beliefs and practices.</p>'), ('Getting started', 'How do I choose a practice mode?', '<p>Choose Key concepts for definitions, Focused practice for B/C/D questions, or A full paper for a complete component structure. Use the <a href="/worksheets/">Worksheet workspace</a> to select and arrange your own questions.</p>'), ('Getting started', 'Do I need a student account?', '<p>No student account is needed on the public website. Browser drafts belong to the current tab, so export your practice if you want to keep it. Admin login is for managing the site.</p>'), ('Getting started', 'Should I also use re.ibzz.uk?', '<p>Yes. ReRevi was inspired by <a href="https://re.ibzz.uk">re.ibzz.uk</a> and is intended to supplement it. Use that website alongside ReRevi as part of your revision.</p>'), ('Getting started', 'Where can I find articles?', '<p>Open Articles from the navigation. Published articles chosen for the sidebar also appear there as direct links.</p>'), ('Questions and marking', 'What do A, B, C and D mean?', '<p>A is a 2-mark definition question. B is a 5-mark description question, C an 8-mark explanation question and D a 15-mark discussion question. Use the question instructions and marking criteria to guide the type of response required.</p>'), ('Questions and marking', 'What happens when I select a past-paper year?', '<p>Year-filtered practice uses official questions from that year. In full paper mode this includes the original Part A keyword for each section. Extra practice is excluded even if its checkbox was selected. Generated papers are unofficial practice documents; use the original-question links to view the source papers.</p>'), ('Questions and marking', 'Can random practice repeat a question?', '<p>Yes. Random selection can show a question you saw in an earlier set. A generated set selects different records, but similar wording can exist in different sources. The worksheet workspace lets you choose or replace individual questions.</p>'), ('Questions and marking', 'How do I leave out extra practice questions?', '<p>Untick Include extra practice questions in the practice builder. In the Worksheet workspace, tick Omit extra practice questions or choose an official source filter. Worksheet omission affects new selection: remove or rebuild existing extra questions if you do not want to keep them.</p>'), ('Questions and marking', 'Why does an extra question have no indicative content?', '<p>Some additional questions were supplied or written without a question-specific mark scheme. They are labelled as additional practice. General official band criteria describe answer quality, not the particular points expected for that question. Self-marking is optional; you can share your answer for feedback.</p>'), ('Questions and marking', 'Does ReRevi mark my answers automatically?', '<p>No. The running application selects stored questions and does not use AI to generate questions or mark answers. Compare your response with available guidance and enter your own self-mark. Additional practice prompts were prepared separately and stored in the bank.</p>'), ('Questions and marking', 'Are my self-marks official exam results?', '<p>No. Self-marks are your own practice estimates. Indicative content is a guide rather than an exhaustive checklist, and accurate alternative answers may receive credit. A teacher can help you judge uncertain answers.</p>'), ('Questions and marking', 'When can I include SPaG marks?', '<p>SPaG is an optional practice setting for eligible 1(d) questions in Components 1 and 2. It is not offered for Component 3 Islam. Turning it off changes your practice total, not the rules of the actual examination.</p>'), ('Questions and marking', 'Why might D instructions differ from an old paper?', '<p>Official D prompts in generated practice use updated instructions while retaining links to the historical originals. Component 1 Life and Death discussion questions also require consideration of non-religious beliefs, such as Humanism and Atheism.</p>'), ('Saving and practice files', 'Will my answers still be there after I close the tab?', '<p>Do not rely on it. Current practice is stored in browser session storage, which normally lasts for that tab; browser session recovery may sometimes restore it. Export a practice file with answers or save answers as text before closing the tab.</p>'), ('Saving and practice files', 'What is a .rerevi file?', '<p>It is a JSON-based practice file containing a snapshot of your questions, their order, source details, available guidance and worksheet settings. It can optionally include answers, plans, flags and self-marks. It is not a PDF or proof that the questions form an official exam paper.</p>'), ('Saving and practice files', 'How do I export and reopen the same practice?', '<p>Open the Worksheet workspace, or choose Save / edit practice set after building a paper. Click Export practice file. Later, choose Open .rerevi file to restore the exact saved set, including your position and any work you chose to include.</p>'), ('Saving and practice files', 'How do I include my answers in a practice file?', '<p>Tick Include typed answers, plans, flags and self-marks before exporting. It is optional and off by default. Keep answer-containing files private. You can also export answers separately as text.</p>'), ('Saving and practice files', 'Can I reopen a practice file on another device?', '<p>Yes. Transfer the file to that device, open ReRevi and import it in the Worksheet workspace. Opening the file reads it locally in your browser; it does not automatically upload your answers or create a sharing link. ReRevi is not currently a guaranteed offline application.</p>'), ('Saving and practice files', 'Do practice files include private deletion links?', '<p>No. Practice exports exclude private sharing and deletion keys. Save your separate private deletion details or submission receipt when you share answers.</p>'), ('Saving and practice files', 'What happens if a saved question has been corrected?', '<p>The workspace can compare saved questions with the current published bank and show correction or availability notices. It preserves the wording in your saved file. Replace a question or rebuild if you want current wording.</p>'), ('Saving and practice files', 'What is saved in a worksheet template?', '<p>A template stores worksheet settings, print preferences and selected question identifiers on that device using local browser storage. It contains no typed answers or sharing keys. Delete it using the template controls. Questions no longer published are omitted when loading a template.</p>'), ('Printing and worksheets', 'What is the difference between PDF and a practice file?', '<p>A PDF is for viewing or printing a paper. A .rerevi file restores an interactive worksheet and can optionally contain your work. Question PDFs do not contain your typed answers; use the answers export or a practice file with answers for that.</p>'), ('Printing and worksheets', 'Can I mix topics and reorder questions?', '<p>Yes. Filter the worksheet bank by component, topics, styles, source or collection. Add questions, move them up or down, remove them, or replace one with an available alternative. You can preview all selected questions before downloading.</p>'), ('Printing and worksheets', 'Why can I not build to a particular mark total?', '<p>The current filters may not provide an exact combination of question marks. Try another total or broaden the filters. The target-mark builder selects an exact match where one is available within the worksheet size limit.</p>'), ('Printing and worksheets', 'Can I print answer booklets and larger text?', '<p>Yes. The workspace offers question papers, lined answer booklets, marking packs and continuation sheets. Choose standard, large-print or compact layouts, extra writing lines, page breaks and wider binding margins for double-sided printing. Matching documents use a paper reference.</p>'), ('Printing and worksheets', 'Why do worksheet versions sometimes overlap?', '<p>Alternative versions keep matching components, sections, styles and sources where possible. If too few alternatives exist, some questions can overlap. The version controls show a notice when alternatives are limited.</p>'), ('Printing and worksheets', 'Is the word count a marking rule?', '<p>No. It is an optional writing aid. There is no automatic mark penalty based on the displayed count; answer the question and use the relevant criteria rather than aiming for a particular number of words.</p>'), ('Sharing and privacy', 'What does creating an answer-sharing link upload?', '<p>It uploads a read-only snapshot of the selected questions, typed answers and self-marks with your optional name and worksheet submission label. Worksheet plans are not shared. Anyone with the viewing link can read the snapshot. Sharing requires your explicit action.</p>'), ('Sharing and privacy', 'How can I remove a shared submission after closing the tab?', '<p>Save the separate private deletion link by copying it, downloading its details or emailing yourself a draft. Open it later and confirm deletion, or paste it at <a href="/s/manage/">Remove shared answers</a>. No account is required. Keep the private link separate from the viewing link sent to your teacher.</p>'), ('Sharing and privacy', 'What if I lose my private deletion link?', '<p>The normal viewing link cannot authorise deletion. Automatic expiry still applies: choose a lifetime of 1, 7, 14 or 29 days, with stored snapshots scheduled for deletion within 30 days of creation. For help, email <a href="mailto:rerevi@zafirshirazi.com">rerevi@zafirshirazi.com</a>.</p>'), ('Sharing and privacy', 'Does editing my answer update an existing sharing link?', '<p>No. A link contains a snapshot from when it was created. Create a replacement link for updated answers. Replacement attempts to delete the previous snapshot shown in the tab; keep its deletion details in case it cannot be removed.</p>'), ('Sharing and privacy', 'What can the administrator see about shared submissions?', '<p>The submission manager shows only the optional name, submission date and deletion controls. It does not provide submitted answers or sharing/deletion links. The owner can remove a shared snapshot if needed.</p>'), ('Sharing and privacy', 'Does deleting a snapshot remove copies someone saved?', '<p>No. It removes the server snapshot and stops its viewing link from working. Copies a recipient has already downloaded, printed, emailed or otherwise saved are outside the server deletion process.</p>'), ('Sharing and privacy', 'Does the feedback email button send automatically?', '<p>No. It opens a draft in your email application for you to review and send. For long answers, ReRevi may download a text file for you to attach manually. The site does not automatically attach files or send the teacher feedback email.</p>'), ('Troubleshooting and feedback', 'Why will my practice file not open?', '<p>Check that you selected a .rerevi practice export rather than a PDF or answers text file. The file must use the supported format and be smaller than 2 MB. Invalid question data, duplicate identifiers or invalid self-marks can prevent import. Keep the original file and <a href="/feedback/">report the issue</a> if it was exported by ReRevi.</p>'), ('Troubleshooting and feedback', 'What should I do if a copy button does not work?', '<p>Your browser may block clipboard access. Select the link in the displayed field and copy it manually. Be careful to send only the viewing link to your teacher and keep the deletion link private.</p>'), ('Troubleshooting and feedback', 'What if browser storage is unavailable?', '<p>Your work may remain only on the current page. Avoid refreshing or closing it until you export your practice or answers. Worksheet templates may not save in browsers that restrict local storage.</p>'), ('Troubleshooting and feedback', 'How do I report a question or marking problem?', '<p>Use Report an issue beside a bank question to include its reference automatically. Otherwise use the <a href="/feedback/">feedback form</a> and include the component, year or source, question number and what appears wrong. Read <a href="/updates/">Updates &amp; known issues</a> first if helpful.</p>'), ('Troubleshooting and feedback', 'What details help with a website bug report?', '<p>Include your device and browser, the page or practice mode, the steps you took, what you expected and what happened. Avoid posting private deletion links, passwords or your answers in the report.</p>'), ('Troubleshooting and feedback', 'Can I send a suggestion without an email address?', '<p>Yes. Name and reply email are optional in the feedback form. Feedback is private to site administrators rather than published. Without a reply address, the owner cannot reply directly. Feedback is kept until deleted, with up to 30 further days in database backups; this is separate from shared-answer expiry.</p>'), ('Troubleshooting and feedback', 'Where can I get more help?', '<p>Use the <a href="/feedback/">feedback form</a> or email <a href="mailto:rerevi@zafirshirazi.com">rerevi@zafirshirazi.com</a>. You can also read the <a href="/articles/">articles</a> and <a href="/privacy/">About &amp; privacy</a> page.</p>')]

def seed_faqs(apps,schema_editor):
    FAQ=apps.get_model('practice','FAQ')
    positions={}
    for category,question,answer in FAQ_DATA:
        position=positions.get(category,0)
        FAQ.objects.create(category=category,question=question,answer=answer,position=position,published=True)
        positions[category]=position+10

class Migration(migrations.Migration):
    dependencies=[('practice','0008_article')]
    operations=[migrations.CreateModel(name='FAQ',fields=[
        ('id',models.BigAutoField(auto_created=True,primary_key=True,serialize=False,verbose_name='ID')),
        ('question',models.CharField(max_length=250)),
        ('answer',models.TextField(max_length=20000)),
        ('category',models.CharField(max_length=80,default='Getting started',help_text='Group related questions under the same category name.')),
        ('position',models.PositiveSmallIntegerField(default=0,help_text='Lower numbers appear first within the category.')),
        ('published',models.BooleanField(default=False)),
        ('updated_at',models.DateTimeField(auto_now=True)),
    ],options={'ordering':['category','position','question'],'verbose_name':'FAQ','verbose_name_plural':'FAQs'}),migrations.RunPython(seed_faqs,migrations.RunPython.noop)]
